        console.log("- 비디오 트랙:", localStream.getVideoTracks().length);
        console.log("- 오디오 트랙:", localStream.getAudioTracks().length);
    }
    console.log("mediasoup 소켓 상태:", mediasoupSocket?.connected);
    console.log("ChatSocket 상태:", chatSocket?.readyState);
    console.log("Consumers 수:", consumers.size);
    console.log("원격 비디오 수:", remoteVideos.size);
    console.log("원격 사용자 정보:", Array.from(remoteUserInfo.entries()));

    return {
        currentUser,
        isJoined,
        hasLocalStream: !!localStream,
        mediasoupConnected: mediasoupSocket?.connected,
        chatSocketState: chatSocket?.readyState,
        consumersCount: consumers.size,
        remoteVideosCount: remoteVideos.size,
        remoteUsersCount: remoteUserInfo.size
    };
};

// mediasoup 재연결 함수
scwin.forceReconnect = function() {
    if (!isJoined) {
        console.log("❌ 화상통화에 참가하지 않은 상태");
        scwin.addChatMessage("시스템", "❌ 먼저 화상통화에 참가해주세요.", false);
        return;
    }

    console.log("mediasoup 강제 재연결 시작...");
    scwin.addChatMessage("시스템", "화상통화 연결을 재시작합니다...", false);

    // mediasoup 연결 재시작
    setTimeout(async () => {
        try {
            // 현재 연결 정리
            scwin.leaveCall();

            // 3초 후 재연결
            setTimeout(async () => {
                try {
                    await scwin.joinCall();
                    scwin.addChatMessage("시스템", "✅ 화상통화 재연결 완료", false);
                } catch (error) {
                    console.error("❌ 재연결 실패:", error);
                    scwin.addChatMessage("시스템", "❌ 재연결 실패. 다시 시도해주세요.", false);
                }
            }, 3000);

        } catch (error) {
            console.error("❌ 연결 정리 실패:", error);
        }
    }, 1000);
};

// 5초마다 자동 상태 체크 (mediasoup 버전)
setInterval(() => {
    if (isJoined) {
        const status = scwin.checkSystemStatus();
        // mediasoup 연결 상태 체크
        if (!status.mediasoupConnected) {
            console.warn("⚠️ mediasoup 서버 연결이 끊어졌습니다!");
        }
        if (status.remoteUsersCount > 0 && status.consumersCount === 0) {
            console.warn("⚠️ 원격 사용자가 있지만 Consumer가 없습니다!");
        }
    }
}, 5000);

