// 콘솔에서 사용할 수 있는 디버깅 함수들 (mediasoup 버전)
window.webRTCUtils = {
    // 현재 상태 체크
    status: () => {
        if (typeof scwin !== 'undefined' && scwin.checkSystemStatus) {
            return scwin.checkSystemStatus();
        }
        return "scwin을 사용할 수 없습니다";
    },

    // 강제 재연결
    reconnect: () => {
        if (typeof scwin !== 'undefined' && scwin.forceReconnect) {
            scwin.forceReconnect();
            return "재연결을 시작했습니다";
        }
        return "scwin을 사용할 수 없습니다";
    },

    // 완전 재시작 (나가기 → 참가하기)
    restart: () => {
        console.log("완전 재시작 시작...");
        const joinBtn = document.getElementById("joinBtn");
        const leaveBtn = document.getElementById("leaveBtn");

        // 현재 참가 중이면 나가기
        if (leaveBtn && leaveBtn.style.display !== "none") {
            leaveBtn.click();
            console.log("1️⃣ 나가기 완료");

            // 5초 후 재참가
