            }, 5000);

            return "5초 후 자동으로 재참가됩니다";
        } else if (joinBtn && joinBtn.style.display !== "none") {
            joinBtn.click();
            return "참가하기를 시도했습니다";
        }

        return "상태를 확인할 수 없습니다";
