    // 도움말
    help: () => {
        console.log(`
=== mediasoup 화상통화 디버깅 명령어들 ===
webRTCUtils.status()     - 현재 상태 확인
webRTCUtils.reconnect()  - 강제 재연결 시도  
webRTCUtils.restart()    - 완전 재시작 (나가기→참가하기)
webRTCUtils.help()       - 이 도움말 표시

=== 사용 예시 ===
1. 상태 확인: webRTCUtils.status()
2. 연결 안될 때: webRTCUtils.reconnect()  
3. 완전 초기화: webRTCUtils.restart()
        `);
        return "도움말을 콘솔에 출력했습니다";
    }
};

