        // Consumer 생성 함수
        async function createConsumer(producerId, userName) {
            try {
                console.log('������ Consumer 생성 시작:', { producerId, userName });

                if (!recvTransport) {
                    console.error('❌ Receive Transport가 없습니다');
                    return;
                }

                // Receive Transport 연결 상태 확인 (PeerConnection 접근 방법 개선)
                let recvPeerConnection = recvTransport._pc || 
                                        recvTransport._handler?.pc || 
                                        recvTransport.handler?.pc;

                console.log('������ Receive Transport 상태 확인:', {
                    hasPeerConnection: !!recvPeerConnection,
                    connectionState: recvPeerConnection?.connectionState,
                    iceConnectionState: recvPeerConnection?.iceConnectionState,
                    signalingState: recvPeerConnection?.signalingState,
                    transportClosed: recvTransport.closed,
                    transportConnectionState: recvTransport.connectionState,
                    receivers: recvPeerConnection?.getReceivers()?.length || 0
                });

                // Transport가 연결될 때까지 대기
                if (recvPeerConnection && recvPeerConnection.connectionState !== 'connected') {
                    console.log('⏳ Receive Transport 연결 대기 중... 현재 상태:', recvPeerConnection.connectionState);
                    await waitForTransportConnection(recvTransport);
                } else if (!recvPeerConnection) {
                    console.log('⚠️ Receive PeerConnection을 찾을 수 없음. Consumer 생성 계속 진행');
                }

                console.log('������ 서버에 Consumer 생성 요청');
                const response = await new Promise((resolve, reject) => {
                    const timeout = setTimeout(() => {
                        reject(new Error('Consumer 생성 요청 시간 초과'));
                    }, 15000);

                    mediasoupSocket.emit('consume', {
                        rtpCapabilities: device.rtpCapabilities,
                        producerId: producerId
                    }, (response) => {
                        clearTimeout(timeout);

                        console.log('������ 서버 응답 수신:', {
                            success: response.success,
                            hasError: !!response.error,
                            error: response.error,
                            hasConsumerId: !!response.consumerId,
                            consumerId: response.consumerId,
                            kind: response.kind,
                            hasRtpParameters: !!response.rtpParameters
                        });

                        if (!response.success) {
                            console.error('❌ 서버에서 Consumer 생성 실패:', response.error);
                            reject(new Error(response.error || 'Consumer 생성 실패'));
                        } else if (!response.consumerId) {
                            console.error('❌ 서버 응답에 consumerId가 없음:', response);
                            reject(new Error('Consumer ID가 없습니다'));
                        } else {
                            console.log('✅ 서버에서 Consumer 생성 성공');
                            resolve(response);
                        }
                    });
                });

                console.log('������ Consumer 생성 응답:', response);

                // Consumer 생성
                const consumer = await recvTransport.consume({
                    id: response.consumerId,
                    producerId: producerId, // 원래 요청한 producerId 사용
                    kind: response.kind,
                    rtpParameters: response.rtpParameters
                });

                console.log('✅ Consumer 생성 완료:', {
                    id: consumer.id,
                    kind: consumer.kind,
                    producerId: consumer.producerId,
                    paused: consumer.paused,
                    closed: consumer.closed
                });

                // Consumer 생성 후 Transport 상태 재확인
                console.log('������ Consumer 생성 후 Transport 상태:', {
                    connectionState: recvTransport._pc?.connectionState,
                    iceConnectionState: recvTransport._pc?.iceConnectionState,
                    receivers: recvTransport._pc?.getReceivers()?.length || 0
                });

                // Consumer resume
                console.log('▶️ Consumer resume 시작');
                await new Promise((resolve, reject) => {
                    const timeout = setTimeout(() => {
                        console.warn('⚠️ Consumer resume 시간 초과. 계속 진행합니다.');
                        resolve();
                    }, 10000);

                    mediasoupSocket.emit('resumeConsumer', {
                        consumerId: consumer.id
                    }, (response) => {
                        clearTimeout(timeout);
                        if (response && response.success) {
                            console.log('✅ Consumer resume 성공');
                            resolve();
                        } else {
                            console.error('❌ Consumer resume 실패:', response?.error);
                            reject(new Error(response?.error || 'Consumer resume 실패'));
                        }
                    });
                });

                // Consumer 이벤트 리스너 설정
                consumer.on('transportclose', () => {
                    console.log('������ Consumer transport closed');
                });

                consumer.on('producerclose', () => {
                    console.log('������ Consumer producer closed');
                });

                consumer.on('trackended', () => {
                    console.log('������ Consumer track ended');
                });

                // Consumer 저장
                consumers.set(consumer.id, {
                    consumer: consumer,
                    producerId: producerId,
                    userName: userName,
                    kind: response.kind
                });

                console.log('✅ Consumer 저장 완료:', {
                    consumerId: consumer.id,
                    totalConsumers: consumers.size
                });

                // Consumer 안정화 대기
                console.log('⏳ Consumer 안정화 대기 중...');
                await new Promise(resolve => setTimeout(resolve, 1000));

                // Transport에서 직접 MediaStream 추출 시도
                await extractMediaStreamFromTransport(recvTransport, consumer, userName);

            } catch (error) {
                console.error('❌ Consumer 생성 실패:', error);
            }
        }

        // Transport에서 MediaStream 추출 함수
        async function extractMediaStreamFromTransport(transport, consumer, userName) {
            try {
                console.log('������ Transport에서 MediaStream 추출 시도');

                // PeerConnection 찾기 (여러 방법 시도)
                const pc = transport._pc || 
                          transport._handler?.pc || 
                          transport.handler?.pc;

                if (!pc) {
                    console.error('❌ PeerConnection을 찾을 수 없습니다:', {
                        transportKeys: Object.keys(transport),
                        hasHandler: !!transport._handler,
                        handlerKeys: transport._handler ? Object.keys(transport._handler) : null
                    });
                    return;
                }

                console.log('������ PeerConnection 상태:', {
                    connectionState: pc.connectionState,
                    iceConnectionState: pc.iceConnectionState,
                    signalingState: pc.signalingState,
                    iceGatheringState: pc.iceGatheringState
                });

                // 모든 Receiver 확인
                const receivers = pc.getReceivers();
                console.log('������ 총 RTP Receivers:', receivers.length);

                if (receivers.length === 0) {
                    console.error('❌ RTP Receiver가 없습니다. Transport 연결 문제일 수 있습니다.');
                    return;
                }

                // 각 Receiver 상세 정보
                receivers.forEach((receiver, index) => {
                    console.log(`������ Receiver ${index}:`, {
                        track: !!receiver.track,
                        trackKind: receiver.track?.kind,
                        trackId: receiver.track?.id,
                        trackEnabled: receiver.track?.enabled,
                        trackReadyState: receiver.track?.readyState,
                        trackMuted: receiver.track?.muted
                    });
                });

                // Live track 수집
                const liveTracks = receivers
                    .map(receiver => receiver.track)
                    .filter(track => track && track.readyState === 'live');

                console.log(`������ Live track 개수: ${liveTracks.length}`);

                if (liveTracks.length > 0) {
                    const stream = new MediaStream(liveTracks);
                    console.log('✅ MediaStream 생성 완료:', {
                        id: stream.id,
                        tracks: stream.getTracks().length,
                        videoTracks: stream.getVideoTracks().length,
                        audioTracks: stream.getAudioTracks().length
                    });

                    // 비디오 표시
                    displayRemoteVideo(stream, userName || 'Unknown');
                } else {
                    console.log('⏳ Live track이 없습니다. 잠시 후 다시 시도합니다.');

                    // 3초 후 재시도
                    setTimeout(() => {
                        extractMediaStreamFromTransport(transport, consumer, userName);
                    }, 3000);
                }

            } catch (error) {
                console.error('❌ MediaStream 추출 실패:', error);
            }
        }
